const r=await tools.exec_command({cmd:"python - <<'PY'
import sys,numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools');from rcb_brush import Session
s=Session(instance='/app/instance.json'); a=np.load('/app/output/trajectory.npz')['actions']; s.reset()
for x in a:s.step(x)
print('strokes',len(s.strokes()),'last',s.status if False else '')
ss=s.strokes(); print('press pcts',np.percentile([z['max_press_mm'] for z in ss],[0,25,50,75,90,100])); print('length pcts',np.percentile([z['length_mm'] for z in ss],[0,25,50,75,90,100]));
im=s.canvas();Image.fromarray(im).save('/tmp/candidate.png');Image.fromarray(s.target_image()).save('/tmp/target.png');ink=s.ink();print('area', (ink>=.5).sum(), 'coverage range',np.percentile(ink,[50,75,90,95,99,100]))
PY",yield_time_ms:30000,max_output_tokens:1000}); text(r.output); if (r.session_id) text("SESSION "+r.session_id); const v=await tools.view_image({path:"/tmp/candidate.png",detail:"high"}); image(v.image_url);

